(function(E){ const x = E["exam-06"] = E["exam-06"] || {units:{}}; (x.units = x.units || {})["x06-l3"] = {"id":"x06-l3","patterns":["L3-humanities","PARA-opinion"],"title":{"en":"Listening Part 3: revising an assignment","tr":"Listening Part 3: bir ödevi gözden geçirmek","fa":"Listening Part 3: بازنگری یک تکلیف"},"objective":{"en":"In this lesson you will learn to follow two students as they work through a tutor’s comments: match each section of their work to the right comment, and answer A-C questions about their reasons and opinions.","tr":"Bu derste bir hocanın yorumlarını tek tek ele alan iki öğrenciyi takip etmeyi öğreneceksin: çalışmalarının her bölümünü doğru yorumla eşleştirecek ve nedenleri ile görüşleri hakkındaki A-C sorularını cevaplayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را وقتی نظرهای استاد را یکی‌یکی بررسی می‌کنند دنبال کنی: هر بخش از کارشان را با نظر درست جور کنی و به سؤال‌های A-C درباره‌ی دلیل‌ها و نظرهایشان جواب بدهی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 3: revising an assignment","tr":"Listening Part 3: bir ödevi gözden geçirmek","fa":"Listening Part 3: بازنگری یک تکلیف"},"objective":{"en":"In this lesson you will learn to follow two students as they work through a tutor’s comments: match each section of their work to the right comment, and answer A-C questions about their reasons and opinions.","tr":"Bu derste bir hocanın yorumlarını tek tek ele alan iki öğrenciyi takip etmeyi öğreneceksin: çalışmalarının her bölümünü doğru yorumla eşleştirecek ve nedenleri ile görüşleri hakkındaki A-C sorularını cevaplayacaksın.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را وقتی نظرهای استاد را یکی‌یکی بررسی می‌کنند دنبال کنی: هر بخش از کارشان را با نظر درست جور کنی و به سؤال‌های A-C درباره‌ی دلیل‌ها و نظرهایشان جواب بدهی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Options in the box","tr":"Kutudaki seçenek","fa":"گزینه‌های کادر"},"value":"A-G"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: an assignment on commuting","tr":"Bu sınav: işe gidip gelme üzerine bir ödev","fa":"این آزمون: تکلیفی درباره‌ی رفت‌وآمد روزانه"},"intro":{"en":"Part 3 is always about study. Humanities and social science projects, like this geography assignment, are the most common kind. Tutor feedback, section by section, is a frequent structure for the matching task.","tr":"Part 3 her zaman ders çalışmayla ilgilidir. Bu coğrafya ödevi gibi beşerî ve sosyal bilim projeleri en sık çıkan türdür. Bölüm bölüm hoca geri bildirimi, eşleştirme görevi için sık kullanılan bir yapıdır.","fa":"Part 3 همیشه درباره‌ی درس است. پروژه‌های علوم انسانی و اجتماعی، مثل این تکلیف جغرافیا، رایج‌ترین نوع‌اند. بازخورد استاد، بخش به بخش، ساختاری رایج برای تمرین جورکردن است."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x06-l3-ctx","exam":true,"patterns":["L3-humanities","PARA-opinion"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Two students revise an assignment plan","tr":"İki öğrenci bir ödev planını gözden geçiriyor","fa":"دو دانشجو برنامه‌ی یک تکلیف را بازنگری می‌کنند"},"asks":{"en":"Two students go through their tutor’s comments on each section of a plan, then talk about why they chose the topic, what surprised them, a theory they read about, who does what and what to do next.","tr":"İki öğrenci hocalarının planın her bölümüne yaptığı yorumları gözden geçiriyor, sonra konuyu neden seçtiklerini, onları neyin şaşırttığını, okudukları bir kuramı, işi kimin yapacağını ve sırada ne olduğunu konuşuyor.","fa":"دو دانشجو نظرهای استادشان را درباره‌ی هر بخش از برنامه مرور می‌کنند و بعد درباره‌ی اینکه چرا این موضوع را انتخاب کردند، چه چیزی غافلگیرشان کرد، نظریه‌ای که خوانده‌اند، تقسیم کار و قدم بعدی حرف می‌زنند."},"fields":["Tutor’s comment on each section","Why this topic","A surprising finding","A theory","Who does what","Next step"],"words":[{"a":"too long","b":"much longer than it needs to be / needs cutting","tr":"çok uzun","fa":"خیلی طولانی"},{"a":"unclear","b":"hard to follow / confusing","tr":"belirsiz","fa":"نامفهوم"},{"a":"out of date","b":"old figures / not the latest data","tr":"güncel değil","fa":"قدیمی، به‌روز نشده"},{"a":"leave out","b":"drop / remove completely","tr":"çıkarmak","fa":"حذف کردن"},{"a":"compare with","b":"set it beside something similar","tr":"... ile karşılaştırmak","fa":"مقایسه کردن با"},{"a":"commute","b":"travel to work every day","tr":"işe gidip gelmek","fa":"رفت‌وآمد روزانه به کار"},{"a":"hardly changed","b":"stayed about the same","tr":"neredeyse hiç değişmedi","fa":"تقریباً تغییر نکرد"},{"a":"I’m not convinced","b":"I doubt it / I’m not sure it’s true","tr":"ikna olmadım","fa":"قانع نشده‌ام"},{"a":"it makes sense for me to","b":"I’m the right person to","tr":"benim yapmam mantıklı","fa":"منطقی است که من"},{"a":"that’s fair","b":"she’s right / good point","tr":"haklı","fa":"منصفانه است، درست می‌گوید"},{"a":"fancy","b":"want to do / like the idea of","tr":"canı istemek","fa":"دلش خواستن"},{"a":"the reason was","b":"honestly, it was... / it was because","tr":"nedeni şuydu","fa":"دلیلش این بود"}],"traps":[{"en":"In the matching task, the comment may mention a box option that does not apply: \"The title’s fine\" rules out a comment about the title.","tr":"Eşleştirmede yorum, geçerli olmayan bir kutu seçeneğinden söz edebilir: \"Başlık iyi\" başlıkla ilgili bir yorumu eler.","fa":"در تمرین جورکردن، ممکن است نظر به گزینه‌ای از کادر اشاره کند که صدق نمی‌کند: «عنوان خوب است» نظری درباره‌ی عنوان را رد می‌کند."},{"en":"A reason that is ruled out twice: \"It wasn’t the tutor’s idea... it isn’t that there’s more data... honestly, it was me.\" The last reason is the answer.","tr":"İki kez elenen neden: \"Hocanın fikri değildi... daha fazla veri olduğu için değil... açıkçası benim yüzümden.\" Son neden cevaptır.","fa":"دلیلی که دو بار رد می‌شود: «ایده‌ی استاد نبود... به‌خاطر داده‌ی بیشتر نیست... راستش به‌خاطر خودم بود». دلیل آخر جواب است."},{"en":"An opinion with a limit: \"It sounds right, but I doubt it applies to every group.\" The part after but is the speaker’s real view.","tr":"Sınırlı bir görüş: \"Doğru gibi duruyor ama her grup için geçerli olduğundan şüpheliyim.\" But’tan sonraki kısım konuşanın gerçek görüşüdür.","fa":"نظری با محدودیت: «درست به نظر می‌رسد، اما شک دارم برای همه‌ی گروه‌ها صدق کند». بخش بعد از but نظر واقعی گوینده است."}],"example":{"lines":[["Student A","What did she say about the graphs?"],["Student B","She liked the colours. The trouble is, they’re from 2009. She wants this year’s figures."]],"item":"Graphs: A need better colours  B need more recent figures","answer":"B","why":{"en":"The colours are praised. \"From 2009... this year’s figures\" = need more recent figures.","tr":"Renkler övülüyor. \"2009’dan... bu yılın rakamları\" = daha yeni rakamlar gerekiyor.","fa":"از رنگ‌ها تعریف می‌شود. «مال ۲۰۰۹... عددهای امسال» یعنی به عددهای تازه‌تر نیاز دارند."}}},{"id":"L3-edu","ctx":["L3-edu","L3-humanities"],"title":{"en":"Study skills, placements and careers","tr":"Çalışma becerileri, stajlar ve kariyer","fa":"مهارت مطالعه، کارآموزی و مسیر شغلی"},"asks":{"en":"Two students, sometimes with a tutor, plan or review a project on a work placement, teaching practice, a library or career plans. Questions ask what they decide, what they think of a source or a method, what went wrong and what they will do next.","tr":"İki öğrenci, bazen bir hocayla, bir staj, öğretmenlik uygulaması, bir kütüphane ya da kariyer planları üzerine bir projeyi planlar ya da değerlendirir. Sorular neye karar verdiklerini, bir kaynak ya da yöntem hakkında ne düşündüklerini, neyin ters gittiğini ve sırada ne yapacaklarını sorar.","fa":"دو دانشجو، گاهی با یک استاد، پروژه‌ای درباره‌ی یک کارآموزی، تمرین تدریس، یک کتابخانه یا برنامه‌های شغلی را برنامه‌ریزی یا بررسی می‌کنند. سؤال‌ها می‌پرسند به چه تصمیمی می‌رسند، درباره‌ی یک منبع یا روش چه فکر می‌کنند، چه چیزی خراب شد و قدم بعدی‌شان چیست."},"fields":["What did the student find most useful about the placement?","What does the tutor advise?","Which TWO skills does the student want to improve?","What is the student’s plan after the course?"],"words":[{"a":"placement","b":"time working in a real job during the course","tr":"staj","fa":"کارآموزی"},{"a":"tutor","b":"the teacher who supervises you","tr":"danışman hoca","fa":"استاد راهنما"},{"a":"feedback","b":"comments on your work","tr":"geri bildirim","fa":"بازخورد"},{"a":"assignment","b":"the piece of written work","tr":"ödev","fa":"تکلیف"},{"a":"deadline","b":"the date you must hand it in","tr":"son teslim tarihi","fa":"مهلت تحویل"},{"a":"reflect on","b":"think about what you learned","tr":"üzerine düşünmek","fa":"تأمل کردن درباره‌ی"},{"a":"case study","b":"one real example in detail","tr":"vaka çalışması","fa":"مطالعه‌ی موردی"},{"a":"confidence","b":"believing you can do it","tr":"özgüven","fa":"اعتمادبه‌نفس"},{"a":"time management","b":"organising your hours","tr":"zaman yönetimi","fa":"مدیریت زمان"},{"a":"supervisor","b":"the person in charge of you at work","tr":"iş yerindeki sorumlu","fa":"سرپرست"},{"a":"career","b":"the job you want long-term","tr":"kariyer","fa":"مسیر شغلی"},{"a":"appendix","b":"extra pages at the end of a report","tr":"ek","fa":"پیوست"}],"traps":[{"en":"Tutor and student can disagree. The question may ask for the tutor’s view, not the student’s.","tr":"Hoca ve öğrenci aynı fikirde olmayabilir. Soru öğrencinin değil hocanın görüşünü sorabilir.","fa":"استاد و دانشجو ممکن است هم‌نظر نباشند. سؤال شاید نظر استاد را بخواهد، نه دانشجو."},{"en":"\"Most useful\" and \"most enjoyable\" are different questions about the same placement.","tr":"\"En faydalı\" ile \"en keyifli\" aynı staj hakkında iki ayrı sorudur.","fa":"«مفیدترین» و «لذت‌بخش‌ترین» دو سؤال متفاوت درباره‌ی همان کارآموزی‌اند."}],"example":{"lines":[["Tutor","What did you get most out of?"],["Student","Well, I loved working with the animals."],["Student","But honestly, the most useful thing was watching how the vets talked to worried owners."]],"item":"What was most useful for the student?  A working with animals   B learning how to talk to owners   C using the equipment","answer":"B","why":{"en":"Working with animals was enjoyable. \"The most useful thing\" was watching the vets talk to owners.","tr":"Hayvanlarla çalışmak keyifliydi. \"En faydalı şey\" veterinerlerin sahiplerle konuşmasını izlemekti.","fa":"کار با حیوان‌ها لذت‌بخش بود. «مفیدترین چیز» دیدن طرز حرف زدن دامپزشک‌ها با صاحبان حیوان بود."}},"general":true,"patterns":["L3-humanities"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"A box of seven, then five A-C questions","tr":"Yedili bir kutu, sonra beş A-C sorusu","fa":"یک کادر هفت‌تایی، بعد پنج سؤال A-C"},"body":{"en":"Questions 21-25: five sections of the work and a box of seven comments, A-G. Choose FIVE answers: each letter once, two left over. Questions 26-30: choose A, B or C. You read Questions 21-25 first and Questions 26-30 in the break.","tr":"Soru 21-25: çalışmanın beş bölümü ve A-G arası yedi yorumluk bir kutu. BEŞ cevap seç: her harf bir kez, ikisi artar. Soru 26-30: A, B ya da C’yi seç. Önce Soru 21-25’i, molada Soru 26-30’u okursun.","fa":"سؤال‌های ۲۱ تا ۲۵: پنج بخش از کار و کادری با هفت نظر، A تا G. پنج جواب انتخاب کن: هر حرف یک بار، دو تا اضافه. سؤال‌های ۲۶ تا ۳۰: A، B یا C را انتخاب کن. اول ۲۱ تا ۲۵ را می‌خوانی و در وقفه ۲۶ تا ۳۰ را."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Section name, then comment","tr":"Önce bölüm adı, sonra yorum","fa":"اول اسم بخش، بعد نظر"},"steps":[{"en":"Underline the key idea of each comment in the box: shorter, labels, newer figures, leave out, compare.","tr":"Kutudaki her yorumun ana fikrinin altını çiz: shorter, labels, newer figures, leave out, compare.","fa":"زیر ایده‌ی اصلی هر نظرِ کادر خط بکش: shorter، labels، newer figures، leave out، compare."},{"en":"Listen for the name of each section; the comment follows within a few lines.","tr":"Her bölümün adını dinle; yorum birkaç satır içinde gelir.","fa":"به اسم هر بخش گوش بده؛ نظر چند خط بعدش می‌آید."},{"en":"For A-C questions, wait for the speaker’s final reason or view: earlier ones are often ruled out.","tr":"A-C sorularında konuşanın son nedenini ya da görüşünü bekle: öncekiler çoğu zaman elenir.","fa":"در سؤال‌های A-C منتظر دلیل یا نظر آخر گوینده بمان: قبلی‌ها اغلب رد می‌شوند."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Praise is not the comment","tr":"Övgü yorum değildir","fa":"تعریف یعنی نظر اصلی نیست"},"body":{"en":"Tutors often praise something before they criticise it: \"She liked it, but...\" The box usually describes what must change, so the answer comes after but. A part that is \"fine\" is not the answer for that section.","tr":"Hocalar çoğu zaman eleştirmeden önce över: \"Beğendi ama...\" Kutu genelde neyin değişmesi gerektiğini anlatır, yani cevap but’tan sonra gelir. \"İyi\" denen bir kısım o bölümün cevabı değildir.","fa":"استادها اغلب قبل از انتقاد تعریف می‌کنند: «خوشش آمد، اما...». کادر معمولاً می‌گوید چه چیزی باید عوض شود، پس جواب بعد از but می‌آید. بخشی که «خوب است» جواب آن بخش نیست."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A reason question, step by step","tr":"Bir neden sorusu, adım adım","fa":"یک سؤال دلیل، قدم به قدم"},"instruction":"Choose the correct letter, A, B or C.","item":"Why did the student choose this project? A The tutor suggested it.  B It was easy to find books.  C She has a personal interest.","lines":[["Student","The tutor did mention it, but I’d already decided. And there aren’t many books on it, actually. My grandmother worked in a mill, so I wanted to know more."]],"answer":"C","walk":[{"en":"A: the tutor \"did mention it, but I’d already decided\" = not the reason.","tr":"A: hoca \"söz etti ama ben çoktan karar vermiştim\" = neden bu değil.","fa":"A: استاد «اشاره کرد، اما من از قبل تصمیم گرفته بودم» یعنی دلیل این نیست."},{"en":"B: \"there aren’t many books on it\" = the opposite.","tr":"B: \"bu konuda pek kitap yok\" = tersi.","fa":"B: «کتاب زیادی درباره‌اش نیست» یعنی برعکس."},{"en":"C: her grandmother’s work = a personal interest.","tr":"C: büyükannesinin işi = kişisel bir ilgi.","fa":"C: کارِ مادربزرگش یعنی علاقه‌ی شخصی."}]},"quick":{"prompt":"\"The conclusion? She said it’s well written, but it just repeats the introduction.\" Which comment matches the conclusion?","options":["It needs new points, not repetition.","It is badly written.","It is too short."],"correct":0,"why":{"en":"\"Well written\" is praise; \"but it just repeats the introduction\" is the real comment.","tr":"\"İyi yazılmış\" övgü; \"ama sadece girişi tekrarlıyor\" asıl yorum.","fa":"«خوب نوشته شده» تعریف است؛ «اما فقط مقدمه را تکرار می‌کند» نظر اصلی است."}},"remember":{"en":"Name, then comment: wait for the word after but, and cross out each letter once you have used it.","tr":"Önce ad, sonra yorum: but’tan sonraki kelimeyi bekle ve kullandığın her harfin üstünü çiz.","fa":"اول اسم، بعد نظر: منتظر کلمه‌ی بعد از but بمان و هر حرفی را که استفاده کردی خط بزن."},"type":"explain","id":"c-x06-l3-e","course":"ielts-exams","exam":"exam-06","unit":"x06-l3"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 3","title":{"en":"An assignment on commuting","tr":"İşe gidip gelme üzerine bir ödev","fa":"تکلیفی درباره‌ی رفت‌وآمد روزانه"},"timed":7,"ctx":["L3-humanities"],"script":[{"who":"Mei","line":"OK, Rhys, we've got the tutor's comments on our draft plan, so let's go through them section by section."},{"who":"Rhys","line":"Fine. She liked the overall idea, didn't she? Commuting as an example of how cities are organised."},{"who":"Mei","line":"She did. But she said the introduction goes on for far too long. Two pages before we even say what we're going to study."},{"who":"Rhys","line":"That's fair. I got carried away with the history of railways. I'll cut it down to half a page. The title's fine, she said."},{"who":"Mei","line":"Then the map of commuter flows. She doesn't want us to drop it, but she found it hard to read. The arrows all look the same, and there's no key."},{"who":"Rhys","line":"I can redo it with labels on each arrow, showing the number of people. That should make it much clearer."},{"who":"Mei","line":"Maybe use colours too: one for trains, one for buses and one for cars. Then you can see at a glance which routes depend on the railway."},{"who":"Mei","line":"Good. The survey data was the main problem. We used figures from the last-but-one census, and she pointed out that a much newer survey came out last year."},{"who":"Rhys","line":"I didn't even know about that. So we need to update all the tables?"},{"who":"Mei","line":"Most of them, yes. The pattern probably won't change, but we can't hand in figures that are twelve years old."},{"who":"Rhys","line":"And the interviews? I was quite proud of those."},{"who":"Mei","line":"She said they were interesting, but with only six people they don't really prove anything, and we're already over the word limit. She suggested we leave them out completely."},{"who":"Rhys","line":"That's a shame, but I suppose she's right. What about the case study of our own city?"},{"who":"Mei","line":"She liked it, but she thinks it would mean more if we compared it with a city of a similar size somewhere else, so the reader has something to measure it against. Otherwise it is hard to tell whether anything about our city is unusual, or whether every city of that size looks the same."},{"who":"Rhys","line":"Perhaps one of the northern cities. I'll look for one with good data. There's a city about two hundred miles away that has a very similar population but a much better tram network, so the contrast could be really useful."},{"who":"Mei","line":"Can I ask you something, Rhys? Why did we choose commuting in the first place? I've forgotten. Was it the tutor's idea?"},{"who":"Rhys","line":"No, she suggested housing, but neither of us fancied that. And it isn't that there's more data on commuting: there's loads of data on everything. Honestly, it was me. I spend ninety minutes a day on the train, and I wanted to know if that's normal."},{"who":"Mei","line":"Ha. And is it?"},{"who":"Rhys","line":"Well, that was the surprising part of the census data. I expected journeys to have got shorter, because trains are faster than thirty years ago. But the average commuting time has hardly changed at all. People just live further away. In some towns along the main line, almost half the working population now travels into the city every day."},{"who":"Mei","line":"Which links to that theory we read about, that people always spend roughly an hour a day travelling, whatever the transport."},{"who":"Rhys","line":"Do you believe it?"},{"who":"Mei","line":"It's an interesting idea, and it fits our figures. But I'm not convinced it's true for everyone. Most of the original studies were of men with office jobs. I'm not sure it describes part-time workers or parents doing the school run."},{"who":"Rhys","line":"We should say that in the discussion. So, how shall we split the work?"},{"who":"Mei","line":"I'm doing the statistics module this term, so it makes sense for me to deal with the new survey data. You're better at writing than I am, so maybe you could take the introduction and the comparison."},{"who":"Rhys","line":"Sounds good. And before we meet next week?"},{"who":"Mei","line":"We could email the tutor again, but she said she's away until the twentieth. Booking a room can wait. I think we should both read that article on what's called excess commuting, so we can discuss it properly next time."},{"who":"Rhys","line":"OK, I'll find it in the library database tonight and send you the link."}],"groups":[{"instruction":"Questions 21-25. What comment did the tutor make about each of the following sections of the students’ plan? Choose FIVE answers from the box and write the correct letter, A-G, next to Questions 21-25.","qtype":"matching","bank":["A It should be much shorter.","B It should come earlier in the assignment.","C It needs more recent figures.","D It should include a comparison with another city.","E It needs clearer labels.","F It could be left out.","G It should be checked by a second tutor."],"questions":[{"n":21,"kind":"match","prompt":"the introduction","correct":0,"evidence":"the introduction goes on for far too long","why":{"en":"\"Two pages before we even say what we’re going to study\": it should be shorter. The title is \"fine\" (not the comment).","tr":"\"Ne çalışacağımızı söylemeden önce iki sayfa\": daha kısa olmalı. Başlık \"iyi\" (yorum bu değil).","fa":"«دو صفحه قبل از اینکه حتی بگوییم چه چیزی را بررسی می‌کنیم»: باید کوتاه‌تر شود. عنوان «خوب است» (نظر این نیست)."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":22,"kind":"match","prompt":"the map","correct":4,"evidence":"she found it hard to read","why":{"en":"Not dropped: \"she found it hard to read... there’s no key\" = it needs clearer labels.","tr":"Çıkarılmıyor: \"okumakta zorlandı... açıklaması yok\" = daha açık etiketler gerekiyor.","fa":"حذف نمی‌شود: «خواندنش برایش سخت بود... راهنما ندارد» یعنی برچسب‌های روشن‌تر لازم دارد."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":23,"kind":"match","prompt":"the survey data","correct":2,"evidence":"a much newer survey came out last year","why":{"en":"The figures come from an old census; \"a much newer survey came out last year\" = needs more recent figures.","tr":"Rakamlar eski bir nüfus sayımından; \"geçen yıl çok daha yeni bir araştırma çıktı\" = daha yeni rakamlar gerekiyor.","fa":"عددها از یک سرشماری قدیمی‌اند؛ «پارسال یک بررسی خیلی جدیدتر منتشر شد» یعنی عددهای تازه‌تر لازم است."},"trap":["TR-paraphrase"]},{"n":24,"kind":"match","prompt":"the interviews","correct":5,"evidence":"She suggested we leave them out completely","why":{"en":"\"Interesting\" is praise; \"she suggested we leave them out completely\" = they could be left out.","tr":"\"İlginç\" bir övgü; \"tamamen çıkarmamızı önerdi\" = çıkarılabilir.","fa":"«جالب» تعریف است؛ «پیشنهاد داد کاملاً حذفشان کنیم» یعنی می‌شود حذفشان کرد."},"trap":["TR-ruledout"]},{"n":25,"kind":"match","prompt":"the case study","correct":3,"evidence":"if we compared it with a city of a similar size somewhere else","why":{"en":"\"Compared it with a city of a similar size somewhere else\" = include a comparison with another city.","tr":"\"Başka bir yerdeki benzer büyüklükte bir şehirle karşılaştırırsak\" = başka bir şehirle karşılaştırma ekle.","fa":"«اگر آن را با شهری هم‌اندازه در جای دیگر مقایسه کنیم» یعنی مقایسه با شهری دیگر را اضافه کن."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 26-30. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":26,"kind":"mcq","prompt":"Why did the students choose commuting as their topic?","options":["A One of them has a long journey every day.","B Their tutor suggested it.","C There is more information on it than on other topics."],"correct":0,"evidence":"I spend ninety minutes a day on the train","why":{"en":"The tutor suggested housing, and data is available \"on everything\". The reason: Rhys spends ninety minutes a day on the train.","tr":"Hoca konutu önerdi ve \"her şey hakkında\" veri var. Neden: Rhys günde doksan dakikasını trende geçiriyor.","fa":"استاد مسکن را پیشنهاد داد و درباره‌ی «همه‌چیز» داده هست. دلیل: ریس روزی نود دقیقه در قطار است."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":27,"kind":"mcq","prompt":"What surprised Rhys in the census data?","options":["A Fewer people travel by train.","B Commuting times have stayed about the same.","C Most people now live close to their work."],"correct":1,"evidence":"the average commuting time has hardly changed at all","why":{"en":"He expected shorter journeys, but \"the average commuting time has hardly changed at all\".","tr":"Daha kısa yolculuklar bekliyordu ama \"ortalama yolculuk süresi neredeyse hiç değişmedi\".","fa":"انتظار سفرهای کوتاه‌تر را داشت، اما «میانگین زمان رفت‌وآمد تقریباً هیچ تغییری نکرده»."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":28,"kind":"mcq","prompt":"What is Mei’s opinion of the theory about daily travel time?","options":["A It does not fit their figures.","B It is too old to be useful.","C It may not apply to all groups of people."],"correct":2,"evidence":"I'm not convinced it's true for everyone","why":{"en":"It \"fits our figures\", but she is \"not convinced it’s true for everyone\": part-time workers and parents may be different.","tr":"\"Rakamlarımıza uyuyor\" ama \"herkes için doğru olduğuna ikna olmadı\": yarı zamanlı çalışanlar ve ebeveynler farklı olabilir.","fa":"«با عددهای ما جور است»، اما «قانع نشده که برای همه درست باشد»: کارمندهای پاره‌وقت و پدر و مادرها ممکن است فرق کنند."},"trap":["TR-paraphrase"]},{"n":29,"kind":"mcq","prompt":"How will the students divide the work?","options":["A Mei will take charge of the latest survey results.","B Rhys will do the statistics.","C They will both write the introduction."],"correct":0,"evidence":"it makes sense for me to deal with the new survey data","why":{"en":"Mei is doing the statistics module, so \"it makes sense for me to deal with the new survey data\". Rhys writes the introduction.","tr":"Mei istatistik dersi alıyor, bu yüzden \"yeni anket verilerini benim ele almam mantıklı\". Girişi Rhys yazıyor.","fa":"می درس آمار را می‌گذراند، پس «منطقی است که من داده‌های بررسی جدید را انجام بدهم». ریس مقدمه را می‌نویسد."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":30,"kind":"mcq","prompt":"What will the students do before their next meeting?","options":["A email their tutor","B book a room in the library","C read an article"],"correct":2,"evidence":"we should both read that article","why":{"en":"The tutor is away and the room \"can wait\". They will \"both read that article\".","tr":"Hoca yok ve oda \"bekleyebilir\". İkisi de \"o makaleyi okuyacak\".","fa":"استاد نیست و اتاق «می‌تواند صبر کند». هر دو «آن مقاله را می‌خوانند»."},"trap":["TR-ruledout","TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Mei":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_lily"},"role":"Student"},"Rhys":{"accent":"Northern English","gender":"M","tts":{"engine":"piper","voice":"en_GB-northern_english_male-medium"},"role":"Student"}},"sequence":[{"type":"announcer","text":"Part 3. You will hear two geography students, Mei and Rhys, discussing their tutor’s comments on their assignment plan. First, you have some time to look at Questions 21 to 25."},{"type":"pause","seconds":30,"note":"reading time, Questions 21-25"},{"type":"announcer","text":"Now listen carefully and answer Questions 21 to 25."},{"type":"sfx","note":"quiet study room, pages turning"},{"type":"lines","from":0,"to":14},{"type":"announcer","text":"Before you hear the rest of the discussion, you have some time to look at Questions 26 to 30."},{"type":"pause","seconds":30,"note":"reading time, Questions 26-30"},{"type":"announcer","text":"Now listen and answer Questions 26 to 30."},{"type":"lines","from":15,"to":26},{"type":"announcer","text":"That is the end of Part 3. You now have half a minute to check your answers.","after":30}]},"id":"c-x06-l3-d","course":"ielts-exams","exam":"exam-06","unit":"x06-l3"},"exit":{"type":"exit","items":[{"tests":"paraphrase","point":3,"prompt":"A box option says \"It could be left out.\" Which words in a recording mean the same?","options":["we should move it to the end","we need to add to it","we could drop it completely"],"correct":2,"why":{"en":"To drop something = to leave it out.","tr":"Drop something = bir şeyi çıkarmak.","fa":"drop کردن یعنی حذف کردن."}},{"tests":"word","point":1,"prompt":"\"The data is out of date.\" This means the data is...","options":["too detailed","old and no longer accurate","missing"],"correct":1,"why":{"en":"Out of date = old, not current.","tr":"Out of date = eski, güncel değil.","fa":"out of date یعنی قدیمی و به‌روز نیست."}},{"tests":"method","point":2,"prompt":"In a matching task with sections of an assignment, how do you know you have moved to the next question?","options":["The speakers name the next section","The speakers change their voices","After exactly one minute"],"correct":0,"why":{"en":"The section names (introduction, map, data...) mark each new question.","tr":"Bölüm adları (giriş, harita, veri...) her yeni soruyu işaret eder.","fa":"اسم بخش‌ها (مقدمه، نقشه، داده...) شروع هر سؤال تازه را نشان می‌دهند."}},{"tests":"trap","point":3,"prompt":"\"She liked the photos a lot, but she said they’re far too small to see.\" What is the comment on the photos?","options":["They are excellent.","They should be removed.","They should be bigger."],"correct":2,"why":{"en":"\"Liked them a lot\" is praise; \"far too small to see\" is the real comment.","tr":"\"Çok beğendi\" övgü; \"görülemeyecek kadar küçük\" asıl yorum.","fa":"«خیلی خوشش آمد» تعریف است؛ «آن‌قدر کوچک‌اند که دیده نمی‌شوند» نظر اصلی است."}},{"tests":"trap","point":2,"prompt":"\"It’s an attractive idea, and it fits the data. But I doubt it works for everyone.\" What is the speaker’s view?","options":["The idea is completely wrong.","The idea has limits.","The idea is proved."],"correct":1,"why":{"en":"The speaker accepts part of it but doubts it applies to everyone: a view with limits.","tr":"Konuşan bir kısmını kabul ediyor ama herkes için geçerli olduğundan şüphe ediyor: sınırlı bir görüş.","fa":"گوینده بخشی را می‌پذیرد، اما شک دارد برای همه صدق کند: نظری با محدودیت."}}],"id":"c-x06-l3-x","course":"ielts-exams","exam":"exam-06","unit":"x06-l3"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
